#!/bin/bash
R=$'\033[38;5;204m';G=$'\033[38;5;78m';Y=$'\033[38;5;221m';P=$'\033[38;5;141m';C=$'\033[38;5;80m';D=$'\033[2m';B=$'\033[1m';N=$'\033[0m'
info(){ echo -e "  ${P}>${N} $1"; }
ok(){ echo -e "  ${G}+${N} $1"; }
die(){ echo -e "  ${R}x FAILED:${N} $1"; exit 1; }
ask(){ echo -ne "  ${C}?${N} $1 "; }
line(){ printf '%*s' "$1" '' | tr ' ' '-'; }
box(){
  local w=46 a t n pl pr
  echo -e "  ${P}.$(line $w).${N}"
  for a in "$@"; do
    t="${a%%|*}"; n=${#t}
    [[ "$a" == *"|"* ]] && n="${a##*|}"
    pl=$(( (w-n)/2 )); pr=$(( w-n-pl ))
    echo -e "  ${P}|${N}$(printf '%*s' $pl '')${B}${t}${N}$(printf '%*s' $pr '')${P}|${N}"
  done
  echo -e "  ${P}'$(line $w)'${N}"
}
spin(){
  local m="$1" f='|/-\' i=0 p rc; shift
  ( "$@" >/dev/null 2>&1 ) &
  p=$!
  tput civis 2>/dev/null
  while kill -0 $p 2>/dev/null; do
    printf "\r  ${P}%s${N} ${D}%s...${N}" "${f:$((i%4)):1}" "$m"
    i=$((i+1)); sleep .12
  done
  wait $p; rc=$?
  printf "\r\033[K"; tput cnorm 2>/dev/null
  return $rc
}
