banner(){
  local cols w k pad l
  cols=$(tput cols 2>/dev/null || echo 80)
  w=60; [ "$cols" -lt 62 ] && w=40
  k=256
  case "${COLORTERM:-}${NEXOR_COLOR:-}" in *truecolor*|*24bit*|*tc*) k=tc;; esac
  pad=$(( (cols-w)/2 )); [ "$pad" -lt 0 ] && pad=0
  "bn_${k}_${w}" | base64 -d | gunzip | while IFS= read -r l; do printf '%*s%s\n' "$pad" '' "$l"; done
}
