s.cpu=Math.max(0,num(b.cpu));s.memory=Math.max(0,num(b.memory));s.swap=num(b.swap);s.disk=Math.max(0,num(b.disk));s.oom=!!b.oom;
if(!s.oom&&s.memory===0)fail(400,'OOM killer can only be disabled with a memory limit');
const imgs=Object.values(e.docker_images);
s.image=imgs.includes(b.image)?b.image:imgs[0];
s.startup=b.startup&&b.startup.trim()?b.startup:e.startup;
s.vars={};
for(const v of e.variables)s.vars[v.env_variable]=String((b.vars||{})[v.env_variable]??v.default_value??'');
};
add('POST','/api/admin/servers',async c=>{
const b=await c.json();
const s={id:uid(),egg:b.egg,status:'installing',suspended:false};
applyServer(s,b,true);
const al=db.allocations.find(a=>a.id===b.allocation&&!a.server);
if(!al)fail(400,'Select a free allocation');
al.server=s.id;al.primary=true;
db.servers.push(s);save();
act(s.id,c.user.email,'server.create',s.name);
install(s).catch(()=>{});
return view(s);
},true);
add('PUT','/api/admin/servers/:id',async c=>{
const s=db.servers.find(x=>x.id===c.p.id);
if(!s)fail(404,'Not found');
applyServer(s,await c.json(),false);
save();act(s.id,c.user.email,'server.edit');return view(s);
},true);
add('POST','/api/admin/servers/:id/suspend',async c=>{
const s=db.servers.find(x=>x.id===c.p.id),b=await c.json();
if(!s)fail(404,'Not found');
s.suspended=!!b.suspend;save();
if(s.suspended)power(s,'kill').catch(()=>{});
return{ok:true};
},true);
add('DELETE','/api/admin/servers/:id',async c=>{
const s=db.servers.find(x=>x.id===c.p.id);
if(!s)fail(404,'Not found');
await run('docker',['rm','-f',nm(s.id)]);
fs.rmSync(volOf(s.id),{recursive:true,force:true});
fs.rmSync(path.join(BK,s.id),{recursive:true,force:true});
db.allocations.forEach(a=>{if(a.server===s.id){a.server=null;delete a.primary}});
db.servers=db.servers.filter(x=>x.id!==s.id);
delete rt[s.id];save();return{ok:true};
},true);
add('GET','/api/admin/settings',async c=>({...db.settings,port:CFG.port}),true);
add('PUT','/api/admin/settings',async c=>{
const b=await c.json();
if(b.name)db.settings.name=String(b.name).slice(0,40);
if(typeof b.host==='string')db.settings.host=b.host.trim();
if(typeof b.domain==='string'){
const d=b.domain.trim().toLowerCase();
if(d&&!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(d))fail(400,'Invalid domain');
if(d!==db.settings.domain){db.settings.domain=d;applyDomain()}
}
save();return db.settings;
},true);
const MIME={'.html':'text/html; charset=utf-8','.js':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.png':'image/png','.ico':'image/x-icon'};
const server=http.createServer(async(req,res)=>{
const u=new URL(req.url,'http://x'),q=Object.fromEntries(u.searchParams);
const send=(c,d)=>{res.writeHead(c,{'Content-Type':'application/json'});res.end(JSON.stringify(d))};
if(!u.pathname.startsWith('/api/')){
let f=path.join(PUB,u.pathname==='/'?'index.html':u.pathname);
if(!f.startsWith(PUB)||!fs.existsSync(f)||fs.statSync(f).isDirectory())f=path.join(PUB,'index.html');
res.writeHead(200,{'Content-Type':MIME[path.extname(f)]||'application/octet-stream'});
return fs.createReadStream(f).pipe(res);
}
try{
for(const r of routes){
if(r.m!==req.method)continue;
const m=r.re.exec(u.pathname);
if(!m)continue;
const ctx={req,res,q,p:m.groups||{},user:null,raw:false};
const rb=()=>new Promise((ok,no)=>{const a=[];let n=0;req.on('data',d=>{n+=d.length;if(n>600*1048576){no({c:413,m:'Too large'});req.destroy()}else a.push(d)});req.on('end',()=>ok(Buffer.concat(a)));req.on('error',no)});
ctx.buf=rb;
ctx.json=async()=>{try{return JSON.parse((await rb()).toString()||'{}')}catch{fail(400,'Invalid JSON')}};
if(u.pathname!=='/api/login'){
const h=req.headers.authorization||'';
ctx.user=verify(h.startsWith('Bearer ')?h.slice(7):q.t);
if(!ctx.user)return send(401,{error:'Unauthorized'});
if(r.admin&&!ctx.user.admin)return send(403,{error:'Admins only'});
}
const out=await r.h(ctx);
if(!ctx.raw)send(200,out===undefined?{ok:true}:out);
return;
}
send(404,{error:'Not found'});
}catch(e){
if(res.headersSent)return res.end();
send(e.c||500,{error:e.m||String(e.message||e)});
}
});
server.listen(CFG.port,'0.0.0.0',()=>console.log('NEXOR HOSTING listening on '+CFG.port));
SERVEREOF
cat > $APP/public/index.html << 'HTMLEOF'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#07080d">
<script>(function(){var t="dark";try{t=localStorage.getItem("nx_theme")||"dark"}catch(e){}document.documentElement.setAttribute("data-theme",t)})()</script>
<title>NEXOR HOSTING v1</title>
<link rel="icon" href="data:image/webp;base64,">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
:root{--bg:#07080d;--s1:rgba(255,255,255,.03);--s2:rgba(255,255,255,.06);--pill:rgba(255,255,255,.1);--bd:rgba(255,255,255,.08);--bd2:rgba(255,255,255,.17);--tx:#eceef7;--mu:#858ba3;--ac:#8b7bff;--ac2:#38e0c8;--rd:#ff6b81;--gn:#3fe0a0;--yl:#ffcb6b;--r:14px;--inp:rgba(255,255,255,.035);--top:rgba(7,8,13,.76);--line:rgba(255,255,255,.2);--sh:none;--g1:rgba(139,123,255,.15);--g2:rgba(56,224,200,.08);--mbg:#0d0f18;--lbg:rgba(14,16,26,.62);--orb:.5;--mono:'JetBrains Mono',ui-monospace,Menlo,Consolas,monospace;color-scheme:dark}
:root[data-theme=light]{--bg:#f4f5fa;--s1:#fff;--s2:#eceef6;--pill:#fff;--bd:rgba(20,24,50,.09);--bd2:rgba(20,24,50,.2);--tx:#141729;--mu:#6a7088;--ac:#5a49f5;--ac2:#0aa995;--rd:#e5384f;--gn:#0f9d65;--yl:#b97d00;--inp:#fff;--top:rgba(244,245,250,.82);--line:rgba(90,73,245,.4);--sh:0 1px 2px rgba(20,24,50,.04),0 10px 26px -14px rgba(20,24,50,.1);--g1:rgba(90,73,245,.08);--g2:rgba(10,169,149,.07);--mbg:#fff;--lbg:rgba(255,255,255,.78);--orb:.28;color-scheme:light}
*{box-sizing:border-box;margin:0;-webkit-tap-highlight-color:transparent}
html{background:var(--bg)}
html,body{min-height:100%;color:var(--tx);font:14.5px/1.5 'Outfit',system-ui,sans-serif;transition:background .3s,color .3s}
body{padding-bottom:env(safe-area-inset-bottom)}
body:before{content:'';position:fixed;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(720px 420px at 8% -10%,var(--g1),transparent 62%),radial-gradient(620px 400px at 100% 0,var(--g2),transparent 62%)}
a{color:inherit;text-decoration:none}
button,input,select,textarea{font:inherit;color:inherit}
::-webkit-scrollbar{width:6px;height:6px}::-webkit-scrollbar-thumb{background:var(--bd2);border-radius:6px}
.top{position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:10px;height:calc(54px + env(safe-area-inset-top));padding:env(safe-area-inset-top) 18px 0;background:var(--top);backdrop-filter:blur(18px) saturate(1.4);-webkit-backdrop-filter:blur(18px) saturate(1.4);border-bottom:1px solid var(--bd)}
.brand{display:flex;align-items:center;gap:9px;font-weight:600;font-size:15px;letter-spacing:.14em;text-transform:uppercase}
.logo{width:28px;height:28px;border-radius:9px;overflow:hidden;flex:none;box-shadow:0 0 0 1px var(--bd),0 4px 14px -4px var(--ac)}
.logo img{width:100%;height:100%;object-fit:cover;display:block}
.nav{display:flex;gap:2px;margin-left:auto;align-items:center}
.nav a,.nav .lo{padding:6px 11px;border-radius:9px;background:none;border:0;color:var(--mu);cursor:pointer;font-size:13.5px;font-weight:500;transition:.15s}
.nav a:hover,.nav .lo:hover{color:var(--tx);background:var(--s2)}
.nav a.on{color:var(--tx);background:var(--s2)}
.ib{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--s2);border:1px solid var(--bd);color:var(--tx);cursor:pointer;flex:none;transition:.18s}
.ib:hover{border-color:var(--bd2);transform:translateY(-1px)}
.ib svg{width:16px;height:16px}
.bk{animation:fade .3s both}
.nav .ib{margin:0 4px}
:root[data-theme=light] .ti .moon{display:none}
:root:not([data-theme=light]) .ti .sun{display:none}
.wrap{max-width:1140px;margin:0 auto;padding:24px 18px 40px;animation:rise .45s cubic-bezier(.2,.8,.2,1) both}
.ft{text-align:center;padding:18px 16px 30px;color:var(--mu);font-size:12px;border-top:1px solid var(--bd);margin-top:30px}
.tabs{display:flex;width:max-content;max-width:100%;gap:2px;overflow-x:auto;margin:16px 0 18px;padding:3px;background:var(--s2);border:1px solid var(--bd);border-radius:11px;scrollbar-width:none}
.tabs::-webkit-scrollbar{display:none}
.tabs a{padding:6px 14px;color:var(--mu);white-space:nowrap;border-radius:8px;font-size:13px;font-weight:500;transition:.15s}
.tabs a.on{color:var(--tx);background:var(--pill);box-shadow:0 1px 3px rgba(0,0,0,.18)}
.tabs a:hover{color:var(--tx)}
.card{position:relative;background:var(--s1);border:1px solid var(--bd);border-radius:var(--r);box-shadow:var(--sh)}
.card:before{content:'';position:absolute;left:16px;right:16px;top:-1px;height:1px;background:linear-gradient(90deg,transparent,var(--line),transparent);pointer-events:none}
.pad{padding:16px}
.grid{display:grid;gap:12px}
.g2{grid-template-columns:repeat(auto-fit,minmax(290px,1fr))}
.g3{grid-template-columns:repeat(auto-fit,minmax(200px,1fr))}
.g4{grid-template-columns:repeat(auto-fit,minmax(150px,1fr))}
h1{font-size:22px;font-weight:600;letter-spacing:-.01em}h2{font-size:15px;font-weight:600;margin-bottom:12px}
.mu{color:var(--mu)}.mono{font-family:var(--mono);font-size:12.5px}
.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.sp{justify-content:space-between}
.btn{display:inline-flex;align-items:center;justify-content:center;height:32px;border:1px solid var(--bd);background:var(--s2);padding:0 14px;border-radius:9px;cursor:pointer;font-size:13px;font-weight:500;transition:.15s;white-space:nowrap}
.btn:hover{border-color:var(--bd2)}
.btn.p{background:linear-gradient(120deg,var(--ac),#5b8cff);border-color:transparent;color:#fff;box-shadow:0 6px 18px -8px var(--ac)}
.btn.p:hover{filter:brightness(1.1)}
.btn.d{background:transparent;border-color:color-mix(in srgb,var(--rd) 40%,transparent);color:var(--rd)}
.btn.d:hover{background:color-mix(in srgb,var(--rd) 12%,transparent)}
.btn.g{background:transparent;border-color:color-mix(in srgb,var(--gn) 45%,transparent);color:var(--gn)}
.btn.g:hover{background:color-mix(in srgb,var(--gn) 12%,transparent)}
.btn.s{height:28px;padding:0 11px;font-size:12.5px;border-radius:8px}
.btn:disabled{opacity:.35;cursor:not-allowed}
input,select,textarea{width:100%;background:var(--inp);border:1px solid var(--bd);border-radius:9px;padding:8px 12px;outline:0;font-size:14px;transition:.15s}
input:focus,select:focus,textarea:focus{border-color:var(--ac);box-shadow:0 0 0 3px color-mix(in srgb,var(--ac) 18%,transparent)}
select option{background:var(--mbg);color:var(--tx)}
textarea{resize:vertical;min-height:90px;font-family:var(--mono);font-size:12.5px}
label{display:block;font-size:12px;color:var(--mu);margin:0 0 5px 2px;font-weight:500}
.f{margin-bottom:12px}
.badge{display:inline-flex;align-items:center;gap:6px;padding:2px 10px;border-radius:99px;font-size:11.5px;font-weight:500;background:var(--s2);border:1px solid var(--bd);color:var(--mu)}
.badge i{width:6px;height:6px;border-radius:50%;background:var(--mu)}
.running{color:var(--gn)}.running i{background:var(--gn);box-shadow:0 0 8px var(--gn)}
.starting i,.installing i,.stopping i{background:var(--yl);animation:blink 1s infinite}.offline i{background:var(--rd)}
.srv{display:block;padding:16px;transition:.2s;overflow:hidden}
.srv:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--ac) 55%,transparent)}
.srv .st{display:grid;grid-template-columns:repeat(3,1fr);margin-top:14px;border-top:1px solid var(--bd);padding-top:12px;gap:8px}
.srv .st div{background:none;padding:0}
.srv .st b{display:block;font-size:13.5px;font-weight:600}.srv .st span{font-size:11px;color:var(--mu)}
.stat{padding:12px 14px;display:flex;gap:12px;align-items:center}
.ico{width:34px;height:34px;border-radius:10px;background:color-mix(in srgb,var(--ac) 13%,transparent);color:var(--ac);display:grid;place-items:center;flex:none}
.ico svg{width:17px;height:17px}
.stat>div:last-child{min-width:0}.stat small{display:block;color:var(--mu);font-size:11.5px}.stat b{font-weight:600;font-size:14px;overflow-wrap:break-word;word-break:normal;min-width:0}
.term{background:#06070b;border:1px solid var(--bd);border-radius:12px;overflow:hidden;box-shadow:var(--sh)}
.term-h{display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid rgba(255,255,255,.06);font-size:11.5px;color:#7d839c;letter-spacing:.06em;text-transform:uppercase}
.dots{display:flex;gap:5px}.dots i{width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,.14)}
.term-h em{margin-left:auto;font-style:normal;display:flex;align-items:center;gap:6px}
.term-h em:before{content:'';width:6px;height:6px;border-radius:50%;background:var(--yl)}
.term-h em.on:before{background:var(--gn);box-shadow:0 0 8px var(--gn)}
.lg{height:min(50vh,400px);overflow:auto;padding:10px 14px;font:12px/1.6 var(--mono);color:#c9cee4;word-break:break-all;white-space:pre-wrap}
.lg div{min-height:1.6em}
.l-p{color:#a99cff}.l-e{color:#ff8296}.l-w{color:#ffd47a}
.term form{display:flex;align-items:center;gap:8px;padding:6px 8px 6px 14px;border-top:1px solid rgba(255,255,255,.06)}
.term .pr{color:var(--ac);font-family:var(--mono);font-size:13px}
.term input{border:0;background:transparent;border-radius:0;padding:6px 0;font:12.5px var(--mono);color:#e4e7f5}
.term input:focus{box-shadow:none;border:0}
.gcard{padding:12px 14px 0;overflow:hidden}
.gh{display:flex;justify-content:space-between;align-items:baseline;font-size:11.5px;color:var(--mu);letter-spacing:.06em;text-transform:uppercase}
.gh b{font-size:13px;letter-spacing:0;color:var(--tx);font-weight:600;text-transform:none}
.gcard canvas{display:block;width:calc(100% + 28px);margin:4px -14px 0;height:96px}
table{width:100%;border-collapse:collapse}
td,th{padding:10px 14px;text-align:left;border-bottom:1px solid var(--bd);font-size:13.5px}
th{color:var(--mu);font-weight:500;font-size:11px;text-transform:uppercase;letter-spacing:.07em}
tr:last-child td{border:0}
.scroll{overflow-x:auto}
.fr{cursor:pointer;transition:.12s}.fr:hover{background:var(--s2)}
.modal{position:fixed;inset:0;z-index:50;background:rgba(3,4,10,.6);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);display:flex;align-items:flex-start;justify-content:center;padding:5vh 14px;overflow:auto;animation:fade .2s both}
.modal .card{width:100%;max-width:620px;background:var(--mbg);padding:20px;animation:pop2 .28s cubic-bezier(.2,.9,.3,1.1) both}
.drop{display:flex;flex-direction:column;align-items:center;gap:2px;padding:18px;border:1px dashed var(--bd2);border-radius:12px;cursor:pointer;margin-bottom:10px;color:var(--tx);font-size:13.5px;font-weight:500;transition:.15s}
.drop small{color:var(--mu);font-weight:400;font-size:12px}
.drop:hover{border-color:var(--ac);background:color-mix(in srgb,var(--ac) 6%,transparent)}
.toast{position:fixed;left:50%;bottom:calc(22px + env(safe-area-inset-bottom));transform:translateX(-50%);z-index:99;padding:9px 16px;border-radius:11px;background:var(--mbg);border:1px solid var(--bd2);box-shadow:0 14px 40px -10px rgba(0,0,0,.5);max-width:90vw;font-size:13.5px;animation:toast .3s cubic-bezier(.2,.9,.3,1.1) both}
.toast.e{border-color:var(--rd);color:var(--rd)}.toast.o{border-color:var(--gn)}
.sw{position:relative;width:38px;height:22px;flex:none}
.sw input{opacity:0;position:absolute;inset:0;width:100%;height:100%;cursor:pointer;z-index:2}
.sw span{position:absolute;inset:0;border-radius:99px;background:var(--bd2);transition:.2s}
.sw span:after{content:'';position:absolute;top:3px;left:3px;width:16px;height:16px;border-radius:50%;background:#fff;transition:.2s}
.sw input:checked+span{background:var(--ac)}.sw input:checked+span:after{transform:translateX(16px)}
#splash{position:fixed;inset:0;z-index:300;display:grid;place-items:center;background:var(--bg);transition:opacity .6s ease,transform .6s ease,visibility .6s}
#splash.out{opacity:0;visibility:hidden;transform:scale(1.04)}
.sp-in{display:flex;flex-direction:column;align-items:center;gap:22px;padding:0 20px}
.sp-logo{width:68px;height:68px;border-radius:20px;position:relative;animation:pop .8s cubic-bezier(.2,.9,.3,1.2) both}
.sp-logo img{width:100%;height:100%;border-radius:inherit;object-fit:cover;display:block}
.sp-logo:after{content:'';position:absolute;inset:-8px;border-radius:26px;border:1px solid var(--ac);opacity:0;animation:ring 1.6s ease-out .3s infinite}
.sp-name{display:flex;flex-wrap:wrap;justify-content:center;font-weight:600;font-size:20px;letter-spacing:.3em;text-transform:uppercase;padding-left:.3em}
.sp-name span{opacity:0;display:inline-block;transform:translateY(10px);filter:blur(6px);animation:ltr .6s ease forwards}
.sp-name .gap{width:.6em}
.sp-bar{width:120px;height:2px;border-radius:2px;background:var(--bd);overflow:hidden}
.sp-bar i{display:block;height:100%;background:linear-gradient(90deg,var(--ac),var(--ac2));transform:translateX(-100%);animation:load 1.4s ease-in-out forwards .2s}
.login{min-height:100vh;display:grid;place-items:center;padding:24px;position:relative;overflow:hidden}
.orb{position:absolute;border-radius:50%;filter:blur(70px);opacity:var(--orb);pointer-events:none}
.o1{width:340px;height:340px;background:var(--ac);top:-90px;left:-70px;animation:fl1 14s ease-in-out infinite}
.o2{width:300px;height:300px;background:var(--ac2);bottom:-80px;right:-60px;animation:fl2 17s ease-in-out infinite}
.o3{width:200px;height:200px;background:#ff7ad9;top:55%;left:58%;opacity:calc(var(--orb) * .5);animation:fl1 20s ease-in-out infinite reverse}
.lt{position:absolute;top:calc(16px + env(safe-area-inset-top));right:16px;z-index:3}
.lcard{position:relative;width:100%;max-width:380px;padding:34px 28px 24px;border-radius:22px;background:var(--lbg);border:1px solid var(--bd);backdrop-filter:blur(22px) saturate(1.3);-webkit-backdrop-filter:blur(22px) saturate(1.3);box-shadow:0 30px 80px -34px rgba(0,0,0,.55);animation:rise .7s cubic-bezier(.2,.8,.2,1) both;z-index:2}
.lcard:before{content:'';position:absolute;left:28px;right:28px;top:-1px;height:1px;background:linear-gradient(90deg,transparent,var(--line),transparent)}
.lcard>*{animation:rise .6s cubic-bezier(.2,.8,.2,1) both}
.lcard>*:nth-child(2){animation-delay:.08s}.lcard>*:nth-child(3){animation-delay:.14s}.lcard>*:nth-child(4){animation-delay:.2s}.lcard>*:nth-child(5){animation-delay:.26s}
.lhead{text-align:center;margin-bottom:24px}
.lg-logo{width:56px;height:56px;border-radius:17px;margin:0 auto 14px;position:relative;box-shadow:0 10px 30px -10px var(--ac)}
.lg-logo img{width:100%;height:100%;border-radius:inherit;object-fit:cover;display:block}
.lg-logo:after{content:'';position:absolute;inset:-6px;border-radius:22px;border:1px solid var(--ac);opacity:0;animation:ring 2.4s ease-out infinite}
.lhead h1{font-size:19px;letter-spacing:.14em;text-transform:uppercase}
.lhead p{color:var(--mu);font-size:13px;margin-top:4px}
.in{position:relative}
.in>svg{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:16px;height:16px;color:var(--mu);pointer-events:none;transition:.15s}
.in input{padding:0 38px;height:40px}
.in:focus-within>svg{color:var(--ac)}
.eye{position:absolute;right:5px;top:50%;transform:translateY(-50%);width:30px;height:30px;border:0;background:none;color:var(--mu);cursor:pointer;display:grid;place-items:center;border-radius:8px}
.eye:hover{color:var(--tx);background:var(--s2)}
.eye svg{width:16px;height:16px}
.btn.big{width:100%;height:42px;font-size:14px;margin-top:8px;border-radius:11px;position:relative}
.spn{position:absolute;width:16px;height:16px;border-radius:50%;border:2px solid rgba(255,255,255,.35);border-top-color:#fff;animation:spin .7s linear infinite;opacity:0}
.loading .spn{opacity:1}.loading span{opacity:0}
.lfoot{text-align:center;color:var(--mu);font-size:11.5px;margin-top:18px}
.shake{animation:shake .4s}
@keyframes fade{from{opacity:0}to{opacity:1}}
@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes pop{from{opacity:0;transform:scale(.6)}to{opacity:1;transform:none}}
@keyframes pop2{from{opacity:0;transform:translateY(10px) scale(.97)}to{opacity:1;transform:none}}
@keyframes toast{from{opacity:0;transform:translate(-50%,12px)}to{opacity:1;transform:translate(-50%,0)}}
@keyframes ltr{to{opacity:1;transform:none;filter:none}}
@keyframes ring{0%{opacity:.6;transform:scale(.92)}100%{opacity:0;transform:scale(1.28)}}
@keyframes load{to{transform:none}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes blink{50%{opacity:.3}}
@keyframes shake{20%,60%{transform:translateX(-6px)}40%,80%{transform:translateX(6px)}}
@keyframes fl1{50%{transform:translate(60px,40px) scale(1.12)}}
@keyframes fl2{50%{transform:translate(-50px,-40px) scale(.9)}}
@media(max-width:720px){.top{padding-left:12px;padding-right:12px;gap:8px}.nav a,.nav .lo{padding:6px 8px;font-size:13px}.wrap{padding:18px 12px 36px}.modal .card{padding:16px}.hide-m{display:none}h1{font-size:20px}}
@media(max-width:720px){.stats{grid-template-columns:1fr 1fr}.stats .stat{padding:10px 11px;gap:9px}.stats .ico{width:30px;height:30px}.stats .stat b{font-size:13px}}
@media(max-width:600px){.brand span{display:none}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation-duration:.01ms!important}}

@property --a{syntax:'<angle>';initial-value:0deg;inherits:false}
@keyframes rot{to{--a:360deg}}
@keyframes bob{50%{transform:translateY(-5px)}}
@keyframes sheen{0%{transform:translateX(-120%)}60%,100%{transform:translateX(120%)}}
@keyframes leave{to{opacity:0;transform:translateY(-12px) scale(.96);filter:blur(6px)}}
@keyframes gridmove{to{background-position:0 38px}}
.login:before{content:'';position:absolute;inset:0;background-image:linear-gradient(var(--bd) 1px,transparent 1px),linear-gradient(90deg,var(--bd) 1px,transparent 1px);background-size:38px 38px;-webkit-mask-image:radial-gradient(ellipse at center,#000 15%,transparent 70%);mask-image:radial-gradient(ellipse at center,#000 15%,transparent 70%);animation:gridmove 3s linear infinite;pointer-events:none}
.lcard:after{content:'';position:absolute;inset:-1px;border-radius:inherit;padding:1px;background:conic-gradient(from var(--a),transparent 55%,var(--ac),var(--ac2),transparent);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;animation:rot 5s linear infinite;pointer-events:none;opacity:.9}
.lcard>.lhead{animation:rise .6s cubic-bezier(.2,.8,.2,1) both}
.lcard.leave{animation:leave .42s ease forwards}
.lg-logo{animation:bob 4s ease-in-out infinite}
.lhead h1{background:linear-gradient(90deg,var(--tx),var(--ac),var(--tx));background-size:200% 100%;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:shine 5s linear infinite}
@keyframes shine{to{background-position:-200% 0}}
.btn.big{overflow:hidden}
.btn.big:after{content:'';position:absolute;top:0;bottom:0;width:40%;left:0;background:linear-gradient(100deg,transparent,rgba(255,255,255,.35),transparent);animation:sheen 3s ease-in-out infinite}
:root[data-theme=light]{--bg:#eceff8;--g1:rgba(90,73,245,.16);--g2:rgba(10,169,149,.13);--sh:0 1px 2px rgba(30,35,80,.05),0 14px 32px -18px rgba(30,35,80,.22);--bd:rgba(30,35,80,.1);--lbg:rgba(255,255,255,.82)}
:root[data-theme=light] .top{background:rgba(255,255,255,.8);box-shadow:0 1px 0 rgba(30,35,80,.04),0 8px 24px -18px rgba(30,35,80,.25)}
:root[data-theme=light] .tabs{background:#e0e4f2}
:root[data-theme=light] .tabs a.on{box-shadow:0 1px 5px rgba(30,35,80,.16)}
:root[data-theme=light] .ico{background:rgba(90,73,245,.1)}
:root[data-theme=light] .ib,:root[data-theme=light] .btn,:root[data-theme=light] .badge{background:#fff}
:root[data-theme=light] .btn.p{background:linear-gradient(120deg,#5a49f5,#4b7bff);color:#fff}
:root[data-theme=light] .btn.d{background:#fff}
:root[data-theme=light] .btn.g{background:#fff}
:root[data-theme=light] .term{border-color:#232842;box-shadow:0 16px 38px -20px rgba(20,24,60,.55)}
:root[data-theme=light] .lcard{box-shadow:0 30px 70px -34px rgba(40,40,110,.35)}
:root[data-theme=light] .orb{filter:blur(80px)}
:root[data-theme=light] .login:before{background-image:linear-gradient(rgba(30,35,80,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(30,35,80,.07) 1px,transparent 1px)}
:root[data-theme=light] .gcard{background:#fff}
.ib span{display:grid;place-items:center;width:100%;height:100%;line-height:0}
.ib svg{display:block;width:16px;height:16px}
.ti{padding:0}
:root[data-theme=light] .ti .moon{display:none}
:root:not([data-theme=light]) .ti .sun{display:none}
</style>
</head>
<body>
<div id="splash"><div class="sp-in"><div class="sp-logo"><img id="sp-img" alt=""></div><div class="sp-name" id="sp-name"></div><div class="sp-bar"><i></i></div></div></div>
<div id="app"></div>
<script>
const LOGO='data:image/webp;base64,';
const $=s=>document.querySelector(s);
const I=p=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`;
const IC={
addr:I('<path d="M12 21s7-5.2 7-11a7 7 0 1 0-14 0c0 5.8 7 11 7 11z"/><circle cx="12" cy="10" r="2.5"/>'),
up:I('<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'),
cpu:I('<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v3M15 2v3M9 19v3M15 19v3M2 9h3M2 15h3M19 9h3M19 15h3"/>'),
mem:I('<rect x="3" y="8" width="18" height="8" rx="1.5"/><path d="M7 8v8M11 8v8M15 8v8M7 19v1M17 19v1"/>'),
disk:I('<ellipse cx="12" cy="6" rx="8" ry="3"/><path d="M4 6v6c0 1.7 3.6 3 8 3s8-1.3 8-3V6M4 12v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6"/>'),
net:I('<path d="M7 4v16M7 4 4 7M7 4l3 3M17 20V4M17 20l-3-3M17 20l3-3"/>'),
srv:I('<rect x="3" y="4" width="18" height="7" rx="2"/><rect x="3" y="13" width="18" height="7" rx="2"/><path d="M7 7.5h.01M7 16.5h.01"/>'),
play:I('<path d="M8 5v14l11-7z"/>'),
user:I('<circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-6 8-6s8 2 8 6"/>'),
egg:I('<path d="M12 3c3.5 0 6.5 5.5 6.5 10a6.5 6.5 0 0 1-13 0C5.5 8.5 8.5 3 12 3z"/>'),
plug:I('<path d="M9 3v5M15 3v5M6 8h12v3a6 6 0 0 1-12 0zM12 17v4"/>'),
box:I('<path d="M12 3 4 7v10l8 4 8-4V7z"/><path d="M4 7l8 4 8-4M12 11v10"/>'),
mail:I('<rect x="3" y="5" width="18" height="14" rx="2.5"/><path d="m4 7 8 6 8-6"/>'),
lock:I('<rect x="5" y="11" width="14" height="9" rx="2.5"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/>'),
eye:I('<path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>'),
eyeoff:I('<path d="M3 3l18 18M10.6 5.1A9.7 9.7 0 0 1 12 5c6.4 0 10 7 10 7a17 17 0 0 1-3.2 4.1M6.5 6.6C3.7 8.4 2 12 2 12s3.6 7 10 7c1.7 0 3.2-.4 4.5-1M9.9 9.9a3 3 0 0 0 4.2 4.2"/>'),
back:I('<path d="M15 5l-7 7 7 7"/>'),
sun:I('<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>'),
moon:I('<path d="M20 14.5A8 8 0 0 1 9.5 4 8 8 0 1 0 20 14.5z"/>')
};
const themeBtn=(c='')=>`<button class="ib ti ${c}" onclick="toggleTheme()" aria-label="Theme"><span class="sun">${IC.sun}</span><span class="moon">${IC.moon}</span></button>`;
function setTheme(t){document.documentElement.dataset.theme=t;try{localStorage.setItem('nx_theme',t)}catch{}const m=document.querySelector('meta[name=theme-color]');if(m)m.content=t==='light'?'#f4f5fa':'#07080d'}
window.toggleTheme=()=>setTheme(document.documentElement.dataset.theme==='light'?'dark':'light');

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={token:localStorage.getItem('sp_token'),user:null,name:'NEXOR HOSTING'};
let es=null,tick=null,cur=null,hist={cpu:[],mem:[],net:[]},lastNet=null,fileState={path:'/',sel:[]};
const fb=n=>{n=+n||0;const u=['B','KiB','MiB','GiB','TiB'];let i=0;while(n>=1024&&i<4){n/=1024;i++}return n.toFixed(i?2:0)+' '+u[i]};
const mbs=n=>n?(n>=1024?(n/1024).toFixed(n%1024?1:0)+' GiB':n+' MiB'):'Unlimited';
const up=ms=>{if(!ms)return '-';let s=Math.floor((Date.now()-ms)/1000);const d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);return (d?d+'d ':'')+(h?h+'h ':'')+m+'m'};
function toast(m,t='o'){const e=document.createElement('div');e.className='toast '+t;e.textContent=m;document.body.appendChild(e);setTimeout(()=>e.remove(),3200)}
async function api(m,p,b,opt={}){
const h={Authorization:'Bearer '+S.token};
let body;
if(b instanceof Blob||b instanceof ArrayBuffer||typeof b==='string'&&opt.text){body=b}
else if(b!==undefined){h['Content-Type']='application/json';body=JSON.stringify(b)}
const r=await fetch('/api'+p,{method:m,headers:h,body});
if(r.status===401&&p!=='/login'){logout();throw new Error('Session expired')}
if(opt.text)return r.ok?r.text():Promise.reject(new Error('Failed'));
const j=await r.json().catch(()=>({}));
if(!r.ok)throw new Error(j.error||'Request failed');
return j;
}
const act=async(fn,ok)=>{try{const r=await fn();if(ok)toast(ok);return r}catch(e){toast(e.message,'e')}};
function logout(){localStorage.removeItem('sp_token');S.token=null;S.user=null;location.hash='';route()}
function modal(html){closeModal();const m=document.createElement('div');m.className='modal';m.id='modal';m.innerHTML='<div class="card">'+html+'</div>';m.addEventListener('mousedown',e=>{if(e.target===m)closeModal()});document.body.appendChild(m)}
function closeModal(){const m=$('#modal');if(m)m.remove()}
const field=(l,i)=>`<div class="f"><label>${l}</label>${i}</div>`;
const sw=(id,on,l)=>`<div class="row sp f"><label style="margin:0">${l}</label><div class="sw"><input type="checkbox" id="${id}" ${on?'checked':''}><span></span></div></div>`;
const dot=s=>`<span class="badge ${s}"><i></i>${s}</span>`;
function shell(inner,active){
const h=location.hash.replace(/^#/,'')||'/';
const sub=!(h==='/'||h==='/all');
return `<div class="top">${sub?`<a class="ib bk" href="#/" aria-label="Back">${IC.back}</a>`:''}<a class="brand" href="#/"><div class="logo"><img src="${LOGO}" alt=""></div><span>${esc(S.name)}</span></a><div class="nav"><a href="#/" class="${active==='home'?'on':''}">Servers</a>${S.user.admin?`<a href="#/admin/overview" class="${active==='admin'?'on':''}">Admin</a>`:''}<a href="#/account" class="${active==='acc'?'on':''}">Account</a>${themeBtn()}<button class="lo" onclick="logout()">Logout</button></div></div><div class="wrap">${inner}</div><div class="ft">&copy; 2026 ${esc(S.name)} &mdash; All Rights Reserved &nbsp;&middot;&nbsp; v1</div>`;
}
function loginView(){
$('#app').innerHTML=`<div class="login"><div class="orb o1"></div><div class="orb o2"></div><div class="orb o3"></div>${themeBtn('lt')}<form class="lcard" id="lf"><div class="lhead"><div class="lg-logo"><img src="${LOGO}" alt=""></div><h1>${esc(S.name)}</h1><p>Sign in to continue to your panel</p></div><div class="f"><label>Email</label><div class="in">${IC.mail}<input name="email" type="email" required autocomplete="username" placeholder="you@example.com"></div></div><div class="f"><label>Password</label><div class="in">${IC.lock}<input name="password" id="lpw" type="password" required autocomplete="current-password" placeholder="Your password"><button type="button" class="eye" id="eye" aria-label="Show password">${IC.eye}</button></div></div><button class="btn p big" id="lb"><span>Sign in</span><i class="spn"></i></button><div class="lfoot">&copy; 2026 ${esc(S.name)}</div></form></div>`;
$('#eye').onclick=()=>{const i=$('#lpw'),on=i.type==='password';i.type=on?'text':'password';$('#eye').innerHTML=on?IC.eyeoff:IC.eye};
$('#lf').onsubmit=async e=>{
e.preventDefault();
const d=Object.fromEntries(new FormData(e.target)),b=$('#lb');
b.classList.add('loading');b.disabled=true;
try{
const r=await api('POST','/login',d);
S.token=r.token;S.user=r.user;S.name=r.name;
localStorage.setItem('sp_token',r.token);
try{localStorage.setItem('nx_name',r.name)}catch{}
const lc=$('#lf');if(lc){lc.classList.add('leave');await new Promise(r=>setTimeout(r,420))}
location.hash='#/';route();
}catch(x){
b.classList.remove('loading');b.disabled=false;
const c=$('#lf');c.classList.remove('shake');void c.offsetWidth;c.classList.add('shake');
toast(x.message,'e');
}
};
}
async function homeView(){
$('#app').innerHTML=shell('<div class="row sp"><h1>Your servers</h1></div><div id="sl" class="grid g3" style="margin-top:16px"></div>','home');
const draw=async()=>{
const l=await api('GET','/servers'+(S.user.admin&&location.hash==='#/all'?'?all=1':''));
const el=$('#sl');if(!el)return;
el.innerHTML=l.length?l.map(s=>`<a class="card srv" href="#/s/${s.id}/console"><div class="row sp"><b style="font-size:16px">${esc(s.name)}</b>${dot(s.suspended?'offline':s.state)}</div><div class="mu mono" style="margin-top:4px">${esc(s.host||'')}:${s.allocations[0]?s.allocations[0].port:'-'}</div><div class="st"><div><b>${s.stats?s.stats.cpu.toFixed(1)+'%':'0%'}</b><span>CPU / ${s.cpu?s.cpu+'%':'∞'}</span></div><div><b>${s.stats?fb(s.stats.mem):'0 B'}</b><span>RAM / ${mbs(s.memory)}</span></div><div><b>${fb(s.diskUsed)}</b><span>Disk / ${mbs(s.disk)}</span></div></div></a>`).join(''):`<div class="card pad mu" style="grid-column:1/-1">No servers yet.${S.user.admin?' Create one from the Admin area.':' Ask an admin to create one for you.'}</div>`;
};
await act(draw);
cur=setInterval(()=>draw().catch(()=>{}),4000);
}
const WV={on:false,raf:0,items:[]};
const rgba=(h,a)=>{const n=parseInt(h.slice(1),16);return `rgba(${n>>16},${n>>8&255},${n&255},${a})`};
function waveInit(list){
WV.items=list.map(o=>({el:document.getElementById(o.id),c:o.c,cl:o.cl,ph:o.ph,max:0,dm:1,data:new Array(40).fill(0),disp:new Array(40).fill(0)}));
if(!WV.on){WV.on=true;WV.raf=requestAnimationFrame(waveLoop)}
}
function waveStop(){WV.on=false;cancelAnimationFrame(WV.raf);WV.items=[]}
function wavePush(i,v,max){const w=WV.items[i];if(!w)return;w.data.push(v);w.data.shift();w.max=max||0}
function waveLoop(ts){
if(!WV.on)return;
const t=ts/1000,n=40;
for(const w of WV.items){
const cv=w.el;
if(!cv||!cv.isConnected)continue;
const dpr=Math.min(window.devicePixelRatio||1,2),W=cv.clientWidth,H=cv.clientHeight;
if(!W||!H)continue;
if(cv.width!==Math.round(W*dpr)||cv.height!==Math.round(H*dpr)){cv.width=Math.round(W*dpr);cv.height=Math.round(H*dpr)}
const x=cv.getContext('2d');
x.setTransform(dpr,0,0,dpr,0,0);
x.clearRect(0,0,W,H);
for(let i=0;i<n;i++)w.disp[i]+=(w.data[i]-w.disp[i])*0.08;
w.dm+=(Math.max(...w.data,1)*1.5-w.dm)*0.04;
const mx=w.max>0?w.max:w.dm;
const layers=[[0,.5,2,1]];
const col=document.documentElement.dataset.theme==='light'?w.cl:w.c;
for(const [off,al,lw,ampk] of layers){
x.beginPath();
for(let px=0;px<=W;px+=2){
const k=px/W*(n-1),i=Math.floor(k),f=k-i,a=w.disp[i],b=w.disp[Math.min(i+1,n-1)],v=a+(b-a)*f;
const lvl=Math.min(v/mx,1);
const amp=(5+lvl*8)*ampk;
const y=H*.68-lvl*H*.42+Math.sin(px*.021+t*1.8+w.ph+off)*amp+Math.sin(px*.047-t*1.15+off*2)*amp*.45;
if(px)x.lineTo(px,y);else x.moveTo(px,y);
}
x.strokeStyle=rgba(col,Math.min(al+.4,1));
x.lineWidth=lw;
x.lineJoin='round';
x.stroke();
x.lineTo(W,H);x.lineTo(0,H);x.closePath();
const g=x.createLinearGradient(0,0,0,H);
g.addColorStop(0,rgba(col,al*.5));
g.addColorStop(1,rgba(col,0));
x.fillStyle=g;
x.fill();
}
}
WV.raf=requestAnimationFrame(waveLoop);
}
const TABS=['console','files','backups','network','startup','settings','activity'];
async function serverView(id,tab){
tab=TABS.includes(tab)?tab:'console';
const s=await api('GET','/servers/'+id);
$('#app').innerHTML=shell(`<div class="row sp"><div><h1 id="sn">${esc(s.name)}</h1><div class="mu">${esc(s.eggName)}</div></div><div class="row" id="pw"></div></div><div class="tabs">${TABS.map(t=>`<a href="#/s/${id}/${t}" class="${t===tab?'on':''}">${t[0].toUpperCase()+t.slice(1)}</a>`).join('')}</div><div id="tb"></div>`,'home');
const pw=st=>{const r=st.state,run=r==='running';$('#pw').innerHTML=`${dot(st.suspended?'offline':r)}<button class="btn g" ${r!=='offline'||st.suspended?'disabled':''} onclick="power('${id}','start')">Start</button><button class="btn" ${!run?'disabled':''} onclick="power('${id}','restart')">Restart</button><button class="btn d" onclick="power('${id}','${r==='stopping'||r==='starting'?'kill':'stop'}')" ${r==='offline'||r==='installing'?'disabled':''}>${r==='stopping'||r==='starting'?'Kill':'Stop'}</button>`};
pw(s);
window.pwDraw=pw;
const T={console:console_,files,backups,network,startup,settings,activity}[tab];
await T(s);
}
window.power=(id,a)=>act(()=>api('POST','/servers/'+id+'/power',{action:a}));
async function console_(s){
lastNet=null;
const a=s.allocations[0];
const stat=(ic,l,id,v,m)=>`<div class="card stat"><div class="ico">${ic}</div><div><small>${l}</small><b id="${id}"${m?' class="mono"':''}>${v}</b></div></div>`;
const gc=(l,id,vid)=>`<div class="card gcard"><div class="gh"><span>${l}</span><b id="${vid}">-</b></div><canvas id="${id}"></canvas></div>`;
$('#tb').innerHTML=`<div class="term"><div class="term-h"><div class="dots"><i></i><i></i><i></i></div><span>Console</span><em id="lv">connecting</em></div><div class="lg" id="lg"></div><form id="cf"><span class="pr">&gt;</span><input id="ci" placeholder="Type a command..." autocomplete="off" autocapitalize="off" spellcheck="false"><button class="btn s p" type="submit">Send</button></form></div><div class="grid g3 stats" style="margin-top:12px">${stat(IC.addr,'Address','s-ad',esc(s.host||'')+':'+(a?a.port:'-'),1)}${stat(IC.up,'Uptime','s-up','-')}${stat(IC.cpu,'CPU load','s-cpu','-')}${stat(IC.mem,'Memory','s-mem','-')}${stat(IC.disk,'Disk','s-dk','-')}${stat(IC.net,'Network in / out','s-net','-')}</div><div class="grid g3" style="margin-top:12px">${gc('CPU','c-cpu','v-cpu')}${gc('Memory','c-mem','v-mem')}${gc('Network','c-net','v-net')}</div>`;
waveInit([{id:'c-cpu',c:'#8b7bff',cl:'#5a49f5',ph:0},{id:'c-mem',c:'#38e0c8',cl:'#0a9a87',ph:2},{id:'c-net',c:'#ffcb6b',cl:'#d48200',ph:4}]);
const lg=$('#lg'),lv=$('#lv');
let part=null;
const strip=t=>t.replace(/\x1b\[[0-9;?]*[A-Za-z]/g,'').replace(/\r/g,'');
const cls=t=>/^\[panel\]/.test(t)?'l-p':/\b(error|ERR!|EACCES|failed|exception|fatal)\b/i.test(t)?'l-e':/\bwarn/i.test(t)?'l-w':'';
const add=t=>{
const b=lg.scrollTop+lg.clientHeight>=lg.scrollHeight-40;
const ls=strip(t).split('\n');
ls.forEach((x,i)=>{
if(!part){part=document.createElement('div');part.dataset.t='';lg.appendChild(part)}
part.dataset.t+=x;part.textContent=part.dataset.t;part.className=cls(part.dataset.t);
if(i<ls.length-1)part=null;
});
while(lg.childElementCount>1200)lg.firstChild.remove();
if(b)lg.scrollTop=lg.scrollHeight;
};
es=new EventSource('/api/servers/'+s.id+'/stream?t='+S.token);
es.onopen=()=>{lv.textContent='live';lv.className='on'};
es.onerror=()=>{lv.textContent='reconnecting';lv.className=''};
es.addEventListener('log',e=>add(JSON.parse(e.data)));
es.addEventListener('stats',e=>{
const st=JSON.parse(e.data);window.pwDraw&&window.pwDraw({...s,...st});
const g=x=>document.getElementById(x);if(!g('s-cpu'))return;
const m=st.stats;
const cpuTxt=m?m.cpu.toFixed(2)+'%':'0%',lim=s.cpu?s.cpu+'%':'Unlimited';
g('s-up').textContent=st.state==='running'?up(st.since):'-';
g('s-cpu').textContent=cpuTxt+' / '+lim;
g('s-mem').textContent=(m?fb(m.mem):'0 B')+' / '+mbs(s.memory);
g('s-dk').textContent=fb(st.diskUsed)+' / '+mbs(s.disk);
g('s-net').textContent=m?fb(m.rx)+' / '+fb(m.tx):'-';
const tot=m?m.rx+m.tx:0,rate=lastNet===null||tot<lastNet?0:(tot-lastNet)/3;
lastNet=m?tot:null;
wavePush(0,m?m.cpu:0,s.cpu||100);
wavePush(1,m?m.mem/1048576:0,s.memory||0);
wavePush(2,rate,0);
g('v-cpu').textContent=cpuTxt;
g('v-mem').textContent=m?fb(m.mem):'0 B';
g('v-net').textContent=fb(rate)+'/s';
});
$('#cf').onsubmit=async e=>{e.preventDefault();const i=$('#ci');const v=i.value;if(!v)return;i.value='';await act(()=>api('POST','/servers/'+s.id+'/command',{cmd:v}))};
}
function crumbs(p){const parts=p.split('/').filter(Boolean);let acc='';return `<a href="javascript:fl('/')" class="mu">home</a>`+parts.map(x=>{acc+='/'+x;return ` / <a href="javascript:fl('${esc(acc)}')">${esc(x)}</a>`}).join('')}
async function files(s){
const p=fileState.path;fileState.sel=[];
const l=await api('GET',`/servers/${s.id}/files?path=${encodeURIComponent(p)}`);
const j=n=>(p==='/'?'':p)+'/'+n;
$('#tb').innerHTML=`<div class="card"><div class="pad row sp"><div class="mono" style="word-break:break-all">${crumbs(p)}</div><div class="row"><button class="btn s d" id="bd" style="display:none" onclick="fdel()">Delete selected</button><button class="btn s" onclick="fnew('dir')">New folder</button><button class="btn s" onclick="fnew('file')">New file</button><label class="btn s p" style="margin:0;color:#fff;cursor:pointer">Upload<input type="file" multiple hidden onchange="fup(this.files)"></label></div></div><div class="scroll"><table><tbody>${p!=='/'?`<tr class="fr" onclick="fl('${esc(p.replace(/\/[^/]*$/,'')||'/')}')"><td></td><td colspan="4">..</td></tr>`:''}${l.map(f=>`<tr class="fr"><td style="width:34px" onclick="event.stopPropagation()"><input type="checkbox" style="width:auto" onchange="fsel('${esc(j(f.name))}',this.checked)"></td><td onclick="${f.dir?`fl('${esc(j(f.name))}')`:`fedit('${esc(j(f.name))}')`}">${f.dir?'[/]':''}${esc(f.name)}</td><td class="mu hide-m">${f.dir?'':fb(f.size)}</td><td class="mu hide-m">${new Date(f.mtime).toLocaleString()}</td><td style="text-align:right;white-space:nowrap">${f.dir?'':`<button class="btn s" onclick="window.open('/api/servers/${s.id}/files/download?t=${S.token}&path='+encodeURIComponent('${esc(j(f.name))}'))">↓</button> `}${/\.(zip|tar|tar\.gz|tgz)$/i.test(f.name)?`<button class="btn s" onclick="fx('${esc(j(f.name))}')">Extract</button> `:''}<button class="btn s" onclick="frn('${esc(j(f.name))}')">Rename</button></td></tr>`).join('')||'<tr><td class="mu pad">Empty directory</td></tr>'}</tbody></table></div></div>`;
window.CS=s;
}
window.fl=p=>{fileState.path=p;route()};
window.fsel=(p,on)=>{const a=fileState.sel;if(on)a.push(p);else a.splice(a.indexOf(p),1);$('#bd').style.display=a.length?'':'none'};
window.fdel=async()=>{if(!confirm('Delete '+fileState.sel.length+' item(s)?'))return;await act(()=>api('POST',`/servers/${CS.id}/files/delete`,{paths:fileState.sel}),'Deleted');route()};
window.fnew=t=>{const n=prompt(t==='dir'?'Folder name':'File name');if(!n)return;const p=(fileState.path==='/'?'':fileState.path)+'/'+n;if(t==='dir')act(()=>api('POST',`/servers/${CS.id}/files/mkdir`,{path:p})).then(route);else fedit(p,true)};
window.frn=async p=>{const n=prompt('New name',p.split('/').pop());if(!n)return;await act(()=>api('POST',`/servers/${CS.id}/files/rename`,{from:p,to:p.replace(/[^/]*$/,'')+n}));route()};
window.fx=async p=>{await act(()=>api('POST',`/servers/${CS.id}/files/extract`,{path:p}),'Extracted');route()};
window.fup=async fs=>{for(const f of fs){await act(()=>api('POST',`/servers/${CS.id}/files/upload?path=${encodeURIComponent(fileState.path)}&name=${encodeURIComponent(f.name)}`,f),'Uploaded '+f.name)}route()};
window.fedit=async(p,isNew)=>{
let t='';if(!isNew)try{t=await api('GET',`/servers/${CS.id}/files/read?path=${encodeURIComponent(p)}`,undefined,{text:true})}catch(e){return toast(e.message,'e')}
modal(`<div class="row sp" style="margin-bottom:12px"><b class="mono" style="word-break:break-all">${esc(p)}</b><button class="btn s" onclick="closeModal()">Close</button></div><textarea id="ed" style="min-height:55vh;white-space:pre;tab-size:2" spellcheck="false">${esc(t)}</textarea><div class="row" style="margin-top:12px;justify-content:flex-end"><button class="btn p" onclick="fsave('${esc(p)}')">Save</button></div>`);
};
window.fsave=async p=>{await act(()=>api('PUT',`/servers/${CS.id}/files/write?path=${encodeURIComponent(p)}`,new Blob([$('#ed').value]),{}),'Saved');closeModal();route()};
async function backups(s){
const l=await api('GET',`/servers/${s.id}/backups`);
$('#tb').innerHTML=`<div class="card"><div class="pad row sp"><h2 style="margin:0">Backups <span class="mu">${l.length}/10</span></h2><button class="btn p" onclick="bk('${s.id}')">Create backup</button></div><div class="scroll"><table><tbody>${l.map(b=>`<tr><td class="mono">${esc(b.name)}</td><td class="mu">${fb(b.size)}</td><td style="text-align:right;white-space:nowrap"><button class="btn s" onclick="window.open('/api/servers/${s.id}/backups/${esc(b.name)}?t=${S.token}')">Download</button> <button class="btn s" onclick="bkr('${s.id}','${esc(b.name)}')">Restore</button> <button class="btn s d" onclick="bkd('${s.id}','${esc(b.name)}')">Delete</button></td></tr>`).join('')||'<tr><td class="mu pad">No backups yet</td></tr>'}</tbody></table></div></div>`;
}
window.bk=async id=>{toast('Creating backup...');await act(()=>api('POST',`/servers/${id}/backups`),'Backup created');route()};
window.bkr=async(id,n)=>{if(!confirm('Restore this backup? Current files will be replaced.'))return;await act(()=>api('POST',`/servers/${id}/backups/${n}/restore`),'Restored');route()};
window.bkd=async(id,n)=>{if(!confirm('Delete backup?'))return;await act(()=>api('DELETE',`/servers/${id}/backups/${n}`),'Deleted');route()};
async function network(s){
$('#tb').innerHTML=`<div class="card"><div class="scroll"><table><thead><tr><th>Host</th><th>Port</th><th></th></tr></thead><tbody>${s.allocations.map((a,i)=>`<tr><td class="mono">${esc(s.host||a.ip)}</td><td class="mono">${a.port}</td><td>${i===0?'<span class="badge running"><i></i>Primary</span>':''}</td></tr>`).join('')}</tbody></table></div></div><p class="mu" style="margin-top:12px">Your app must listen on the primary port. It is also passed as the SERVER_PORT environment variable.</p>`;
}
async function startup(s){
$('#tb').innerHTML=`<div class="grid g2"><div class="card pad"><h2>Startup command</h2><textarea id="su">${esc(s.startup)}</textarea></div><div class="card pad"><h2>Docker image</h2><select id="im">${Object.entries(s.images).map(([k,v])=>`<option value="${esc(v)}" ${v===s.image?'selected':''}>${esc(k)}</option>`).join('')}</select><p class="mu" style="margin-top:8px;font-size:13px">Restart the server after changing the image.</p></div></div><h2 style="margin:20px 0 12px">Variables</h2><div class="grid g2">${s.variables.map(v=>`<div class="card pad"><label>${esc(v.name)} <span class="mono">${esc(v.env_variable)}</span></label><input data-v="${esc(v.env_variable)}" value="${esc(s.vars[v.env_variable]??v.default_value)}" ${v.user_editable===false?'disabled':''}></div>`).join('')}</div><div class="row" style="margin-top:16px;justify-content:flex-end"><button class="btn p" id="sv">Save changes</button></div>`;
$('#sv').onclick=()=>{const vars={};document.querySelectorAll('[data-v]').forEach(i=>vars[i.dataset.v]=i.value);act(()=>api('PUT','/servers/'+s.id,{startup:$('#su').value,image:$('#im').value,vars}),'Saved')};
}
async function settings(s){
$('#tb').innerHTML=`<div class="grid g2"><div class="card pad"><h2>Server details</h2>${field('Server name',`<input id="nm" value="${esc(s.name)}">`)}${field('Server ID',`<input value="${s.id}" readonly class="mono">`)}<div class="row" style="justify-content:flex-end"><button class="btn p" id="sn2">Save</button></div></div><div class="card pad"><h2>Limits</h2><div class="row sp"><span class="mu">CPU</span><b>${s.cpu?s.cpu+'%':'Unlimited'}</b></div><div class="row sp"><span class="mu">Memory</span><b>${mbs(s.memory)}</b></div><div class="row sp"><span class="mu">Swap</span><b>${s.swap<0?'Unlimited':s.swap?mbs(s.swap):'Disabled'}</b></div><div class="row sp"><span class="mu">Disk</span><b>${mbs(s.disk)}</b></div><div class="row sp"><span class="mu">OOM killer</span><b>${s.oom?'Enabled':'Disabled'}</b></div></div><div class="card pad"><h2>Reinstall server</h2><p class="mu" style="margin-bottom:14px">Stops nothing by itself; the server must be offline. Some files may be modified by the egg install script.</p><button class="btn d" onclick="reinst('${s.id}')">Reinstall server</button></div></div>`;
$('#sn2').onclick=()=>act(()=>api('PUT','/servers/'+s.id,{name:$('#nm').value}),'Saved').then(()=>$('#sn').textContent=$('#nm').value);
}
window.reinst=async id=>{if(!confirm('Reinstall this server?'))return;await act(()=>api('POST',`/servers/${id}/reinstall`),'Reinstall started')};
async function activity(s){
const l=await api('GET',`/servers/${s.id}/activity`);
$('#tb').innerHTML=`<div class="card"><div class="scroll"><table><tbody>${l.map(a=>`<tr><td><b>${esc(a.u)}</b> <span class="mu mono">${esc(a.ev)}</span><div class="mu" style="font-size:13px">${esc(a.d)}</div></td><td class="mu" style="text-align:right;white-space:nowrap">${new Date(a.t).toLocaleString()}</td></tr>`).join('')||'<tr><td class="mu pad">No activity yet</td></tr>'}</tbody></table></div></div>`;
}
const ATABS=['overview','servers','users','eggs','allocations','settings'];
async function adminView(tab){
if(!S.user.admin){location.hash='#/';return}
tab=ATABS.includes(tab)?tab:'overview';
$('#app').innerHTML=shell(`<h1>Administration</h1><div class="tabs">${ATABS.map(t=>`<a href="#/admin/${t}" class="${t===tab?'on':''}">${t[0].toUpperCase()+t.slice(1)}</a>`).join('')}</div><div id="tb"></div>`,'admin');
await ({overview:aOverview,servers:aServers,users:aUsers,eggs:aEggs,allocations:aAllocs,settings:aSettings})[tab]();
}
async function aOverview(){
const o=await api('GET','/admin/overview');
const c=(l,v,i)=>`<div class="card stat"><div class="ico">${i}</div><div><small>${l}</small><b style="font-size:20px">${v}</b></div></div>`;
$('#tb').innerHTML=`<div class="grid g4">${c('Servers',o.servers,IC.srv)}${c('Running',o.running,IC.play)}${c('Users',o.users,IC.user)}${c('Eggs',o.eggs,IC.egg)}${c('Free ports',o.free+' / '+o.allocations,IC.plug)}${c('Docker',esc(o.docker),IC.box)}</div>`;
}
async function aServers(){
const [l,u]=await Promise.all([api('GET','/servers?all=1'),api('GET','/admin/users')]);
window.AU=u;
$('#tb').innerHTML=`<div class="card"><div class="pad row sp"><h2 style="margin:0">All servers</h2><button class="btn p" onclick="sform()">Create server</button></div><div class="scroll"><table><thead><tr><th>Name</th><th>Owner</th><th>Egg</th><th>Port</th><th>Limits</th><th></th></tr></thead><tbody>${l.map(s=>`<tr><td><a href="#/s/${s.id}/console"><b>${esc(s.name)}</b></a><div>${dot(s.suspended?'offline':s.state)}</div></td><td class="mu">${esc((u.find(x=>x.id===s.owner)||{}).email||'-')}</td><td class="mu">${esc(s.eggName)}</td><td class="mono">${s.allocations[0]?s.allocations[0].port:'-'}</td><td class="mu" style="font-size:13px">${s.cpu?s.cpu+'%':'∞'} · ${mbs(s.memory)} · ${mbs(s.disk)}</td><td style="text-align:right;white-space:nowrap"><button class="btn s" onclick='sform(${JSON.stringify(s.id)})'>Edit</button> <button class="btn s" onclick="ssus('${s.id}',${!s.suspended})">${s.suspended?'Unsuspend':'Suspend'}</button> <button class="btn s d" onclick="sdel('${s.id}')">Delete</button></td></tr>`).join('')||'<tr><td class="mu pad">No servers</td></tr>'}</tbody></table></div></div>`;
window.AS=l;
}
window.ssus=async(id,v)=>{await act(()=>api('POST',`/admin/servers/${id}/suspend`,{suspend:v}),'Done');route()};
window.sdel=async id=>{if(!confirm('Delete this server and all its files?'))return;await act(()=>api('DELETE','/admin/servers/'+id),'Deleted');route()};
window.sform=async id=>{
const [eggs,al]=await Promise.all([api('GET','/admin/eggs'),api('GET','/admin/allocations')]);
const s=id?AS.find(x=>x.id===id):null;
const free=al.filter(a=>!a.server);
if(!s&&!free.length)return toast('No free allocations. Add ports in Allocations.','e');
window.SF={eggs,s};
modal(`<div class="row sp" style="margin-bottom:14px"><h2 style="margin:0">${s?'Edit server':'Create server'}</h2><button class="btn s" onclick="closeModal()">Close</button></div><div class="grid g2" style="gap:0 14px">${field('Server name',`<input id="f-name" value="${esc(s?s.name:'')}" placeholder="My Server">`)}${field('Owner user',`<select id="f-owner">${AU.map(u=>`<option value="${u.id}" ${s&&s.owner===u.id?'selected':''}>${esc(u.email)}</option>`).join('')}</select>`)}${s?'':field('Egg (server type)',`<select id="f-egg" onchange="sfegg()">${eggs.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select>`)}${field('Docker image / version','<select id="f-img"></select>')}${s?'':field('Allocation (port)',`<select id="f-al">${free.map(a=>`<option value="${a.id}">${esc(a.ip)}:${a.port}</option>`).join('')}</select>`)}${field('CPU limit % (0 = unlimited)',`<input id="f-cpu" type="number" min="0" value="${s?s.cpu:100}">`)}${field('Memory MB (0 = unlimited)',`<input id="f-mem" type="number" min="0" value="${s?s.memory:512}">`)}${field('Swap MB (0 disabled, -1 unlimited)',`<input id="f-swap" type="number" min="-1" value="${s?s.swap:0}">`)}${field('Disk MB (0 = unlimited)',`<input id="f-dk" type="number" min="0" value="${s?s.disk:2048}">`)}</div>${sw('f-oom',s?s.oom:true,'Enable OOM killer (recommended)')}${field('Startup command','<textarea id="f-su" style="min-height:70px"></textarea>')}<div id="f-vars"></div><div class="row" style="justify-content:flex-end"><button class="btn p" id="f-ok">${s?'Save changes':'Create server'}</button></div>`);
sfegg();
$('#f-ok').onclick=async()=>{
const vars={};document.querySelectorAll('[data-fv]').forEach(i=>vars[i.dataset.fv]=i.value);
const b={name:$('#f-name').value,owner:$('#f-owner').value,egg:s?s.egg:$('#f-egg').value,image:$('#f-img').value,cpu:$('#f-cpu').value,memory:$('#f-mem').value,swap:$('#f-swap').value,disk:$('#f-dk').value,oom:$('#f-oom').checked,startup:$('#f-su').value,vars};
if(!s)b.allocation=$('#f-al').value;
const r=await act(()=>s?api('PUT','/admin/servers/'+s.id,b):api('POST','/admin/servers',b),s?'Saved':'Server created, installing...');
if(r){closeModal();route()}
};
};
window.sfegg=()=>{
const {eggs,s}=SF;
const e=eggs.find(x=>x.id===(s?s.egg:$('#f-egg').value));
$('#f-img').innerHTML=Object.entries(e.docker_images).map(([k,v])=>`<option value="${esc(v)}" ${s&&s.image===v?'selected':''}>${esc(k)}</option>`).join('');
$('#f-su').value=s?s.startup:e.startup;
$('#f-vars').innerHTML=e.variables.length?`<h2 style="margin-top:6px">Variables</h2><div class="grid g2">`+e.variables.map(v=>field(`${esc(v.name)} <span class="mono" style="font-size:11px">${esc(v.env_variable)}</span>${v.user_editable===false?'<span class="mu" style="font-size:11px"> (fixed)</span>':''}`,`<input data-fv="${esc(v.env_variable)}" value="${esc(s&&s.vars[v.env_variable]!==undefined?s.vars[v.env_variable]:v.default_value)}" ${v.user_editable===false?'disabled':''}>`)).join('')+'</div>':'';
};
async function aUsers(){
const l=await api('GET','/admin/users');
window.AUL=l;
$('#tb').innerHTML=`<div class="card"><div class="pad row sp"><h2 style="margin:0">Users</h2><button class="btn p" onclick="uform()">New user</button></div><div class="scroll"><table><thead><tr><th>Email</th><th>Username</th><th>Role</th><th>Servers</th><th></th></tr></thead><tbody>${l.map(u=>`<tr><td>${esc(u.email)}</td><td class="mu">${esc(u.username)}</td><td>${u.admin?'<span class="badge running"><i></i>Admin</span>':'<span class="badge"><i></i>User</span>'}</td><td class="mu">${u.servers}</td><td style="text-align:right;white-space:nowrap"><button class="btn s" onclick="viewUserServers('${u.id}','${esc(u.email)}')">Servers</button> <button class="btn s" onclick="uform('${u.id}')">Edit</button> <button class="btn s d" onclick="udel('${u.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div></div>`;
}
window.uform=id=>{
const u=id?AUL.find(x=>x.id===id):null;
modal(`<div class="row sp" style="margin-bottom:14px"><h2 style="margin:0">${u?'Edit user':'New user'}</h2><button class="btn s" onclick="closeModal()">Close</button></div>${field('Email',`<input id="u-e" type="email" value="${esc(u?u.email:'')}">`)}${field('Username',`<input id="u-n" value="${esc(u?u.username:'')}">`)}${field(u?'New password (leave empty to keep)':'Password','<input id="u-p" type="password">')}${sw('u-a',u&&u.admin,'Administrator')}<div class="row" style="justify-content:flex-end"><button class="btn p" id="u-ok">Save</button></div>`);
$('#u-ok').onclick=async()=>{const b={email:$('#u-e').value,username:$('#u-n').value,admin:$('#u-a').checked};if($('#u-p').value)b.password=$('#u-p').value;const r=await act(()=>u?api('PUT','/admin/users/'+u.id,b):api('POST','/admin/users',b),'Saved');if(r){closeModal();route()}};
};
window.udel=async id=>{if(!confirm('Delete user?'))return;await act(()=>api('DELETE','/admin/users/'+id),'Deleted');route()};
window.viewUserServers=async(uid,email)=>{
const servers=await api('GET',`/admin/users/${uid}/servers`);
modal(`<div class="row sp" style="margin-bottom:14px"><h2 style="margin:0">Servers — ${esc(email)}</h2><button class="btn s" onclick="closeModal()">Close</button></div><div class="scroll"><table><thead><tr><th>Name</th><th>Egg</th><th>Port</th><th>Status</th><th></th></tr></thead><tbody>${servers.length?servers.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td class="mu">${esc(s.eggName)}</td><td class="mono">${s.allocations[0]?s.allocations[0].port:'-'}</td><td>${dot(s.suspended?'offline':s.state)}</td><td style="text-align:right;white-space:nowrap"><a href="#/s/${s.id}/console" onclick="closeModal()" class="btn s">Open</a> <button class="btn s" onclick="closeModal();ssus('${s.id}',${!s.suspended})">${s.suspended?'Unsuspend':'Suspend'}</button> <button class="btn s d" onclick="closeModal();sdel('${s.id}')">Delete</button></td></tr>`).join(''):'<tr><td class="mu pad" colspan="5">No servers</td></tr>'}</tbody></table></div>`);
};
async function aEggs(){
const l=await api('GET','/admin/eggs');
window.AE=l;
$('#tb').innerHTML=`<div class="card"><div class="pad row sp"><h2 style="margin:0">Eggs</h2><button class="btn p" onclick="eform()">Import egg</button></div><div class="scroll"><table><thead><tr><th>Name</th><th>Images</th><th>Variables</th><th></th></tr></thead><tbody>${l.map(e=>`<tr><td><b>${esc(e.name)}</b><div class="mu" style="font-size:13px">${esc(e.description||'')}</div></td><td class="mu">${Object.keys(e.docker_images).length}</td><td class="mu">${e.variables.length}</td><td style="text-align:right;white-space:nowrap"><button class="btn s" onclick="eform('${e.id}')">Edit JSON</button> <button class="btn s d" onclick="edel('${e.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div></div>`;
}
window.eform=id=>{
const e=id?AE.find(x=>x.id===id):null;
const j=e?(({id,...r})=>r)(e):'';
modal(`<div class="row sp" style="margin-bottom:14px"><h2 style="margin:0">${e?'Edit egg':'Import egg'}</h2><button class="btn s" onclick="closeModal()">Close</button></div><p class="mu" style="margin-bottom:10px;font-size:13px">Paste a Pterodactyl egg JSON (PTDL_v1 / PTDL_v2) or load a file.</p><label class="drop" for="e-f"><span id="e-fn">Choose a .json egg file</span><small>or paste the JSON below</small></label><input type="file" accept=".json" id="e-f" hidden><textarea id="e-j" style="min-height:28vh;white-space:pre" spellcheck="false">${esc(e?JSON.stringify(j,null,2):'')}</textarea><div class="row" style="justify-content:flex-end;margin-top:12px"><button class="btn p" id="e-ok">${e?'Save':'Import'}</button></div>`);
$('#e-f').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;$('#e-fn').textContent=f.name;$('#e-j').value=await f.text()};
$('#e-ok').onclick=async()=>{const r=await act(()=>e?api('PUT','/admin/eggs/'+e.id,{json:$('#e-j').value}):api('POST','/admin/eggs',{json:$('#e-j').value}),'Saved');if(r){closeModal();route()}};
};
window.edel=async id=>{if(!confirm('Delete egg?'))return;await act(()=>api('DELETE','/admin/eggs/'+id),'Deleted');route()};
async function aAllocs(){
const l=await api('GET','/admin/allocations');
$('#tb').innerHTML=`<div class="grid g2"><div class="card pad"><h2>Add ports</h2>${field('IP address','<input id="a-ip" value="0.0.0.0">')}<div class="grid g2" style="gap:0 12px">${field('Start port','<input id="a-s" type="number" placeholder="25565">')}${field('End port (optional)','<input id="a-e" type="number">')}</div><div class="row" style="justify-content:flex-end"><button class="btn p" id="a-ok">Add</button></div></div><div class="card pad"><h2>Summary</h2><div class="row sp"><span class="mu">Total</span><b>${l.length}</b></div><div class="row sp"><span class="mu">Free</span><b>${l.filter(a=>!a.server).length}</b></div></div></div><div class="card" style="margin-top:14px"><div class="scroll"><table><thead><tr><th>Address</th><th>Assigned to</th><th></th></tr></thead><tbody>${l.map(a=>`<tr><td class="mono">${esc(a.ip)}:${a.port}</td><td class="mu">${esc(a.serverName||'-')}</td><td style="text-align:right">${a.server?'':`<button class="btn s d" onclick="adel('${a.id}')">Remove</button>`}</td></tr>`).join('')}</tbody></table></div></div>`;
$('#a-ok').onclick=async()=>{const r=await act(()=>api('POST','/admin/allocations',{ip:$('#a-ip').value,start:$('#a-s').value,end:$('#a-e').value||$('#a-s').value}),'Added');if(r)route()};
}
window.adel=async id=>{await act(()=>api('DELETE','/admin/allocations/'+id));route()};
async function aSettings(){
const c=await api('GET','/admin/settings');
$('#tb').innerHTML=`<div class="grid g2"><div class="card pad"><h2>Panel</h2>${field('Panel name',`<input id="st-n" value="${esc(c.name)}">`)}${field('Public host / IP shown to users',`<input id="st-h" value="${esc(c.host)}">`)}<div class="row" style="justify-content:flex-end"><button class="btn p" id="st-ok">Save</button></div></div><div class="card pad"><h2>Domain / HTTPS</h2><p class="mu" style="font-size:13px;margin-bottom:12px">Point your domain A record to this server IP first. HTTPS is issued automatically via Caddy. Leave empty to use IP:${c.port}.</p>${field('Domain',`<input id="st-d" placeholder="panel.example.com" value="${esc(c.domain)}">`)}${c.domain?`<p class="mu" style="font-size:12px;margin-bottom:10px">Current: <b>${esc(c.domain)}</b> — HTTPS active</p>`:''}<div class="row"><button class="btn p" id="st-dk">Connect domain</button>${c.domain?'<button class="btn d" id="st-drem">Remove domain</button>':''}</div></div></div>`;
$('#st-ok').onclick=async()=>{const r=await act(()=>api('PUT','/admin/settings',{name:$('#st-n').value,host:$('#st-h').value}),'Saved');if(r)S.name=r.name};
$('#st-dk').onclick=async()=>{const d=$('#st-d').value.trim();if(!d)return toast('Enter a domain first','e');const r=await act(()=>api('PUT','/admin/settings',{domain:d}),'Domain connected! HTTPS will activate shortly.');if(r)route()};
if($('#st-drem'))$('#st-drem').onclick=async()=>{if(!confirm('Remove domain and go back to HTTP?'))return;await act(()=>api('PUT','/admin/settings',{domain:''}),'Domain removed');route()};
}
function accountView(){
$('#app').innerHTML=shell(`<h1>Account</h1><div class="grid g2" style="margin-top:16px"><div class="card pad"><h2>Email and username</h2>${field('Email',`<input id="ac-e" value="${esc(S.user.email)}">`)}${field('Username',`<input id="ac-n" value="${esc(S.user.username)}">`)}${field('Current password','<input id="ac-c1" type="password">')}<div class="row" style="justify-content:flex-end"><button class="btn p" id="ac-1">Save</button></div></div><div class="card pad"><h2>Password</h2>${field('New password','<input id="ac-p" type="password">')}${field('Current password','<input id="ac-c2" type="password">')}<div class="row" style="justify-content:flex-end"><button class="btn p" id="ac-2">Change password</button></div></div></div>`,'acc');
$('#ac-1').onclick=async()=>{const r=await act(()=>api('PUT','/me',{email:$('#ac-e').value,username:$('#ac-n').value,current:$('#ac-c1').value}),'Saved');if(r)S.user=r};
$('#ac-2').onclick=async()=>{const r=await act(()=>api('PUT','/me',{password:$('#ac-p').value,current:$('#ac-c2').value}),'Password changed');if(r){$('#ac-p').value='';$('#ac-c2').value=''}};
}
function cleanup(){waveStop();if(es){es.close();es=null}if(cur){clearInterval(cur);cur=null}}
let lastSrv=null;
async function route(){
cleanup();closeModal();
if(!S.token){loginView();return}
if(!S.user){try{const r=await api('GET','/me');S.user=r.user;S.name=r.name}catch{return}}
const h=location.hash.replace(/^#/,'')||'/',p=h.split('/').filter(Boolean);
try{
if(p[0]==='s'){if(lastSrv!==p[1]){fileState={path:'/',sel:[]};lastSrv=p[1]}await serverView(p[1],p[2])}
else if(p[0]==='admin')await adminView(p[1]);
else if(p[0]==='account')accountView();
else await homeView();
}catch(e){toast(e.message,'e');if(/not found/i.test(e.message))location.hash='#/'}
}
window.addEventListener('hashchange',route);
(function(){
let nm='NEXOR HOSTING';
try{nm=localStorage.getItem('nx_name')||nm}catch{}
const box=document.getElementById('sp-name');
document.getElementById('sp-img').src=LOGO;
[...nm].forEach((ch,i)=>{const s=document.createElement('span');if(ch===' ')s.className='gap';s.textContent=ch===' '?'\u00a0':ch;s.style.animationDelay=(0.15+i*0.05)+'s';box.appendChild(s)});
const t0=Date.now();
route().catch(()=>{}).then(()=>{
try{localStorage.setItem('nx_name',S.name)}catch{}
setTimeout(()=>{const sp=document.getElementById('splash');sp.classList.add('out');setTimeout(()=>sp.remove(),700)},Math.max(0,1700-(Date.now()-t0)));
});
})();
</script>
</body>
</html>
HTMLEOF
PORT=$(node -p "require('$APP/config.json').port")
DOM=$(node -p "require('$APP/config.json').domain")
IP=$(node -p "require('$APP/config.json').host")
if [ -n "$DOM" ]; then
  printf '%s {\n\treverse_proxy 127.0.0.1:%s\n}\n' "$DOM" "$PORT" > /etc/caddy/Caddyfile
  systemctl enable caddy >/dev/null 2>&1
  systemctl restart caddy
else
  systemctl stop caddy >/dev/null 2>&1
  systemctl disable caddy >/dev/null 2>&1
fi
pm2 delete nexorhosting >/dev/null 2>&1
pm2 start $APP/server.js --name nexorhosting --cwd $APP >/dev/null 2>&1
pm2 save >/dev/null 2>&1
pm2 startup systemd -u root --hp /root >/dev/null 2>&1
command -v ufw >/dev/null 2>&1 && ufw allow $PORT/tcp >/dev/null 2>&1
nohup sh -c 'docker pull ghcr.io/parkervcp/yolks:nodejs_20; docker pull ghcr.io/parkervcp/yolks:nodejs_22' >/dev/null 2>&1 &
ok "Panel service started"
echo ""
box "" "NEXOR HOSTING v1" "Installation complete" "" "DEV : 𝑫𝑬𝑽 -/ 𝑺𝑨𝒀𝑨𝑵 𝑲.|21" ""
echo ""
[ -n "$DOM" ] && echo -e "  ${G}+${N} Panel URL   ${B}https://$DOM${N}"
echo -e "  ${G}+${N} Panel URL   ${B}http://$IP:$PORT${N}"
[ -n "$FRESH" ] && echo -e "  ${Y}!${N} Sign in with the email and password you just set"
echo ""
echo -e "  ${D}Domain  ${N} Admin > Settings"
echo -e "  ${D}Ports   ${N} Admin > Allocations (open them in your firewall too)"
echo -e "  ${D}Eggs    ${N} Admin > Eggs > Import"
echo -e "  ${D}Users   ${N} Admin > Users"
echo ""
echo -e "  ${D}(c) 2026 NEXOR HOSTING. All Rights Reserved.${N}"
echo ""
